old_block = '''                elif diff < self._SECS_PER_MONTH * 2:
                    return locale.describe("month", sign, only_distance=only_distance)
                elif diff < self._SECS_PER_YEAR:
                    # TODO revisit for humanization during leap years
                    self_months = self._datetime.year * 12 + self._datetime.month
                    other_months = dt.year * 12 + dt.month

                    months = sign * max(abs(other_months - self_months), 2)

                    return locale.describe(
                        "months", months, only_distance=only_distance
                    )'''

new_block = '''                elif diff < self._SECS_PER_YEAR:
                    # Use shift to calculate actual month difference, handling DST correctly
                    # Start with approximate month count from year/month arithmetic
                    approx_months = abs((dt.year * 12 + dt.month) - (self._datetime.year * 12 + self._datetime.month))

                    # Adjust using shift to handle DST and varying month lengths
                    months_count = approx_months
                    if sign == -1:
                        while months_count > 0:
                            shifted = self.shift(months=months_count, check_imaginary=False)
                            if shifted._datetime <= dt:
                                break
                            months_count -= 1
                    else:
                        while months_count > 0:
                            shifted = self.shift(months=-months_count, check_imaginary=False)
                            if shifted._datetime >= dt:
                                break
                            months_count -= 1

                    if months_count == 1:
                        return locale.describe("month", sign, only_distance=only_distance)
                    else:
                        months = sign * max(months_count, 2)
                        return locale.describe(
                            "months", months, only_distance=only_distance
                        )'''

